// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

// The decision is made here, not by the model: the agent can only get a PENDING row, and only for a slot that
// check_availability offered THIS client for THIS service (Clients.last_offer_json) less than pending_ttl_min minutes ago.
// The calendar is not touched; confirm_booking writes the event after the client's YES (called by WF-1, not by the agent).
const s = ($('Settings').first().json || {}).fields;
if (!s) throw new Error('propose_booking: the Settings table has no row');
const ttl = (s.pending_ttl_min === null || s.pending_ttl_min === undefined || String(s.pending_ttl_min).trim() === '') ? NaN : Number(s.pending_ttl_min);
if (!Number.isFinite(ttl) || ttl <= 0) throw new Error('propose_booking: Settings.pending_ttl_min must be a positive number, got ' + JSON.stringify(s.pending_ttl_min));
const tz = s.timezone;
if (typeof tz !== 'string' || !tz.trim() || !DateTime.now().setZone(tz).isValid) throw new Error('propose_booking: Settings.timezone is missing or not a valid IANA zone, got ' + JSON.stringify(tz));
const inp = $('Trigger').first().json;
const cr = $('Client').first().json || {};   // the whole record: cr.id is the record id, the columns are in cr.fields
const c = cr.fields || {};
// rec_id is the Services record id (for the `service` link), the rest are the columns
const services = $('Services').all().map(i => ({ ...((i.json || {}).fields || {}), rec_id: (i.json || {}).id })).filter(x => x.service_id);
const reject = (verdict) => [{ json: { ok: false, verdict } }];
if (!cr.id || !c.client_id) return reject('NO_CLIENT_ROW');
// client_id goes into the Old Pending formula: anything but a plain id would let a row edit change that formula
if (!/^[A-Za-z0-9_-]{1,64}$/.test(c.client_id)) throw new Error('propose_booking: unexpected Clients.client_id ' + JSON.stringify(String(c.client_id).slice(0, 80)) + ' in record ' + cr.id);
const svc = services.find(x => x.service_id === String(inp.service_id || '').trim().toLowerCase());
if (!svc) return reject('UNKNOWN_SERVICE ' + services.map(x => `${x.service_id} (${x.name}, ${x.duration_min} min)`).join('; '));
const dur = Number(svc.duration_min);
if (!Number.isFinite(dur) || dur <= 0) throw new Error('propose_booking: Services.duration_min of ' + svc.service_id + ' must be a positive number, got ' + JSON.stringify(svc.duration_min));
const start = DateTime.fromISO(String(inp.start_iso || '').trim());
if (!start.isValid) return reject('SLOT_NOT_OFFERED');
// The offer is {service_id, slots} as check_availability saved it. Only slots offered for THIS service count: a slot sized for a
// 30 min service is not free for a 60 min one (it could run past closing or past noon). Slots are compared as instants, so
// 12:00+01:00 and 11:00Z are the same slot. An unreadable offer, or the old plain-array format, is no offer.
let offered = [];
try { const o = JSON.parse(c.last_offer_json || '{}'); if (o && typeof o === 'object' && !Array.isArray(o) && o.service_id === svc.service_id && Array.isArray(o.slots)) offered = o.slots.map(x => DateTime.fromISO(String(x))).filter(d => d.isValid).map(d => d.toMillis()); } catch (e) { offered = []; }
const offeredAt = c.last_offer_at ? DateTime.fromISO(String(c.last_offer_at)) : null;
const age = offeredAt && offeredAt.isValid ? DateTime.utc().diff(offeredAt, 'minutes').minutes : Infinity;
const fresh = age >= -1 && age <= ttl;   // -1: a minute of clock skew between Airtable and n8n
if (!fresh || !offered.includes(start.toMillis())) return reject('SLOT_NOT_OFFERED');
const end = start.plus({ minutes: dur });
const appt_id = 'A-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase();
const iso = (t) => t.setZone(tz).toISO({ suppressMilliseconds: true });
// The name is written only when the row has none (a name the client gave earlier, or the owner typed, is kept).
const cleanName = String(inp.name || '').replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u2028-\u202e\u2066-\u2069\ufeff]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80);
const channel = String(inp.channel || '').trim().toLowerCase();
// replaces_appt_id (a reschedule) is kept only when it names a visit of THIS client that is booked/reminded/confirmed and still
// ahead (Client Appts); anything else is stored as '', so a later cancel of the replaced visit can never reach someone else's.
const want = String(inp.replaces_appt_id || '').trim();
const replaces = want && $('Client Appts').all().map(i => (i.json || {}).fields || {}).some(a => a.appt_id === want && a.client_id === c.client_id && ['booked', 'reminded', 'confirmed'].includes(a.status) && DateTime.fromISO(String(a.start_iso || '')) > DateTime.utc()) ? want : '';
return [{ json: {
  ok: true, client_id: c.client_id, set_name: (!String(c.name || '').trim() && cleanName) ? cleanName : '',
  fields: {
    appt_id, client: [cr.id], client_id: c.client_id, service: [svc.rec_id], service_id: svc.service_id,
    start_iso: iso(start), end_iso: iso(end), start_dt: start.toUTC().toISO(),
    status: 'pending', created_via: ['tg', 'wa', 'test', 'owner'].includes(channel) ? channel : 'tg',
    pending_expires_at: DateTime.utc().plus({ minutes: ttl }).toISO(),
    replaces_appt_id: replaces
  }
} }];
